struct Excerpt {
    text: &str,
}

fn longest(left: &str, right: &str) -> &str {
    if left.len() > right.len() { left } else { right }
}

fn main() {
    let text = String::from("campus power");
    let excerpt = Excerpt { text: &text };
    println!("{}", longest(excerpt.text, "grid"));
}
